-- 二級ボイラー技士
INSERT INTO entities (type, slug, name, category, attributes, official_stats)
VALUES ('certification', 'boiler-2kyu', '二級ボイラー技士', '労働安全衛生', '{"short_name":"二級ボイラー技士","authority":{"name":"公益財団法人 安全衛生技術試験協会","url":"https://www.exam.or.jp/"},"exam":{"eligibility":"試験そのものには受験資格の制限がない。ただし申込時に本人確認証明書の添付が必要。なお試験に合格しても、それだけでは免許が交付されない点に注意(後述)。","fee_yen":8800,"format":"学科試験のみ。実技試験はない。「ボイラーの構造に関する知識」「ボイラーの取扱いに関する知識」「燃料及び燃焼に関する知識」「関係法令」の4科目から、各10問・100点が出題される(合計40問・400点満点)。","questions":40,"duration_minutes":180,"passing_criteria":"科目ごとの得点が40%以上で、かつその合計が60%以上であること。1科目でも40%を下回ると、合計が60%を超えていても不合格になる。","frequency":"北海道・東北・関東(市原)・東京試験場・中部・近畿(大阪)・中国四国・九州の8か所で、月1回程度・年12回実施される(令和8年4月〜令和9年3月の日程で確認)。年1回の一斉試験ではない。","result_announcement":"合格者には「免許試験合格通知書」が郵送され、試験結果はセンターのホームページにも掲載される。電話等による問い合わせには応じない旨が明記されている。試験結果発表日を10日以上過ぎても通知が届かない場合は連絡するよう案内がある。なお試験日から発表日までの日数は、受験地・試験ごとに定められる。","license_requirement":"試験に合格しただけでは免許は交付されない。免許を申請する際に「実務経験等を証する書類」の添付が必要で(試験日が平成24年4月1日以降の場合)、その要件は次のいずれかを満たすこと。(1) ボイラーに関する学科を修めて卒業し、3か月以上の実地修習を経た (2) 6か月以上の実地修習を経た (3) ボイラー取扱技能講習を修了し、4か月以上小規模ボイラーを取り扱った経験がある (4) ボイラー実技講習を修了した (5) 厚生労働大臣が定める者に該当する。実務経験が無い受験者は、(4)のボイラー実技講習を受けるのが一般的な経路になる。","source_urls":{"eligibility":"https://www.exam.or.jp/introduction/h_shokai122/","fee_yen":"https://www.exam.or.jp/h_tesuryo/","format":"https://www.exam.or.jp/introduction/h_shokai122/","questions":"https://www.exam.or.jp/introduction/h_shokai122/","duration_minutes":"https://www.exam.or.jp/introduction/h_shokai122/","passing_criteria":"https://www.exam.or.jp/introduction/h_shokai122/","frequency":"https://www.exam.or.jp/schedule/h_nittei122","result_announcement":"https://www.exam.or.jp/introduction/h_shokai122/","license_requirement":"https://jsite.mhlw.go.jp/kagoshima-roudoukyoku/hourei_seido_tetsuzuki/anzen_eisei/shiken/2019-1011-5.html"},"subjects":["ボイラーの構造に関する知識 10問・100点","ボイラーの取扱いに関する知識 10問・100点","燃料及び燃焼に関する知識 10問・100点","関係法令 10問・100点"],"license_requirement_note":"実施団体(安全衛生技術試験協会)のサイトには「実務経験等を証する書類」が必要という記載までしかなく、その具体的な要件を列挙したページが無い。そのため要件の内訳は、厚生労働省の地方組織である鹿児島労働局が公開している免許交付要件の一覧を出典としている。二次情報のまとめサイトは根拠にしていない。","retrieved_at":"2026-07-26"},"related":[{"slug":"eisei-kanri-1","reason":"同じ安全衛生技術試験協会が実施する免許試験。合格基準の考え方(各科目40%以上かつ合計60%以上)が共通"},{"slug":"eisei-kanri-2","reason":"同上。試験会場と実施体制が同じ"}],"schedule_url":"https://www.exam.or.jp/schedule/h_nittei122","verification":{"collected_by":"researcher(一次ソースのみ)+ PM(Fable)","verified_by":"未実施","verified_at":null,"result":"🔴 独立検証が未実施。特に (1) 免許交付の実務要件を実施団体以外の一次ソース(鹿児島労働局)から取っている点 (2) 統計が令和7年度の1年分のみ。"},"notes":"確認できなかった項目: (1) 試験日から合格発表までの日数。実施日ごとに各センターが個別に公表するため、協会サイトに一律の記載が無い。(2) 出張特別試験を実施する都市の一覧。実施すること自体は公式ページに記載があるが、都市の一覧ページを特定できなかった。いずれも推測で埋めていない。","public_note":"この試験は、合格しても自動的に免許が交付されるわけではありません。免許の申請には実務経験またはボイラー実技講習の修了が必要です。受験を検討する際は、試験の難易度だけでなくこの要件も併せてご確認ください。"}', '{"official_stats":{"unit":"全国集計(安全衛生技術試験協会発表)","series":[{"year":"令和7年度","applicants":null,"examinees":21349,"passers":11303,"pass_rate":52.9,"source_url":"https://www.exam.or.jp/h_gokakuritsu/","retrieved_at":"2026-07-26"}],"source_url":"https://www.exam.or.jp/h_gokakuritsu/","retrieved_at":"2026-07-26","notes":"実施団体の統計ページから令和7年度の値を取得した。申込者数は同ページに掲載が無いため null としている。過去年度の系列は未取得で、次回の更新時に追加する。11,303÷21,349=52.94%で、公表値52.9%と小数第1位まで一致することを検算済み。","unit_labels":{"applicants":"申込者数(未公表)","examinees":"受験者数","passers":"合格者数","pass_rate":"合格率(%)"},"public_note":"実施団体が公表している全国集計です。申込者数は公表されていないため掲載していません。"}}')
ON CONFLICT DO NOTHING;

-- 第一種衛生管理者
INSERT INTO entities (type, slug, name, category, attributes, official_stats)
VALUES ('certification', 'eisei-kanri-1', '第一種衛生管理者', '労働安全衛生', '{"short_name":"第一種衛生管理者","authority":{"name":"公益財団法人 安全衛生技術試験協会","url":"https://www.exam.or.jp/"},"exam":{"eligibility":"受験するには、学歴に応じた労働衛生の実務経験が必要。大学(短期大学を含む)または高等専門学校を卒業した場合は1年以上、高等学校または中等教育学校を卒業した場合は3年以上、学歴を問わない場合は10年以上の実務経験が求められる(このほかにも複数の受験資格が定められている)。いずれの場合も、申込時に事業者が発行する事業者証明書の添付が必要。","fee_yen":8800,"format":"学科試験のみ。第一種衛生管理者は「労働衛生(有害業務)」「労働衛生(その他)」「関係法令(有害業務)」「関係法令(その他)」「労働生理」の5区分から出題される。第二種と異なり、有害業務に関する科目が含まれる。","questions":44,"duration_minutes":180,"passing_criteria":"科目ごと(範囲が分かれているものは範囲ごと)の得点が40%以上で、かつその合計が60%以上であること。1科目でも40%を下回ると、合計が60%を超えていても不合格になる。","frequency":"全国7つの安全衛生技術センター(北海道・東北・関東・中部・近畿・中国四国・九州)と東京・大阪の試験場、計9か所で実施される。年1回の一斉試験ではなく、実施回数は受験地によって大きく異なる。令和8年度の日程では東京試験場・大阪試験場が月4〜9回組まれている一方、近畿センターは月1回程度にとどまる。","result_announcement":"合格の場合は「免許試験合格通知書」、それ以外の場合は「免許試験結果通知書」が本人宛てに届く。試験結果はセンターのホームページにも掲載されるが、実施団体はこれを「受験者の便宜を考慮した補助的な方法」と位置づけており、本人宛ての通知書で確認するよう案内している。試験結果発表日を10日以上過ぎても通知が届かない場合は連絡するよう記載がある。なお試験日から発表日までの日数は、受験地・試験ごとに定められる。","source_urls":{"eligibility":"https://www.exam.or.jp/introduction/h_shokai502/","fee_yen":"https://www.exam.or.jp/h_tesuryo/","format":"https://www.exam.or.jp/introduction/h_shokai502/","questions":"https://www.exam.or.jp/introduction/h_shokai502/","duration_minutes":"https://www.exam.or.jp/introduction/h_shokai502/","passing_criteria":"https://www.exam.or.jp/introduction/h_shokai502/","frequency":"https://www.exam.or.jp/schedule/h_nittei502/","result_announcement":"https://www.exam.or.jp/introduction/h_shokai502/"},"subjects":["労働衛生(有害業務に係るもの) 10問・80点","労働衛生(有害業務に係るもの以外のもの) 7問・70点","関係法令(有害業務に係るもの) 10問・80点","関係法令(有害業務に係るもの以外のもの) 7問・70点","労働生理 10問・100点"],"duration_note":"3時間。科目免除者は2時間15分。","retrieved_at":"2026-07-26"},"related":[{"slug":"eisei-kanri-2","reason":"有害業務を扱わない業種向けの区分。受験資格は同じで、試験科目が少ない"}],"verification":{"collected_by":"PM(Fable)","verified_by":"fact-checker(独立に一次ソースを再取得)+ PM が指摘箇所を再確認","verified_at":"2026-07-26","result":"数値は全て一次ソースと一致。記述側に2件の誤りが見つかり修正した。(1) 合格発表を「確認できなかった」と書いていたが、既に他項目で引用していた同じページに記載があった(掟1-c違反) (2) 実施頻度を「月1〜2回程度」と書いていたが、令和8年度の日程では東京・大阪が月4〜9回、近畿が月1回と受験地で大きく異なる。あわせて受験資格の要約から短期大学・高等専門学校・中等教育学校の欠落を補った。残る課題は過去年度の統計が令和7年度の1年分しか無いこと。"},"notes":"当初「合格発表の時期・方法は確認できなかった」と記載していたが、これは誤りだった。実施団体の試験紹介ページに通知書と結果掲載についての記述があり、独立検証で発見して修正した。試験日から発表日までの日数については、依然として全国一律の記載が無い(受験地・試験ごとに定められるため)。","public_note":"数値はすべて実施団体である安全衛生技術試験協会の公表資料に基づきます。受験には実務経験などの要件があるため、申込前に必ず公式の受験資格をご確認ください。"}', '{"official_stats":{"unit":"全国集計(安全衛生技術試験協会発表)","series":[{"year":"令和7年度","applicants":null,"examinees":66401,"passers":31046,"pass_rate":46.8,"source_url":"https://www.exam.or.jp/h_gokakuritsu/","retrieved_at":"2026-07-26"}],"source_url":"https://www.exam.or.jp/h_gokakuritsu/","retrieved_at":"2026-07-26","notes":"実施団体の統計ページから令和7年度の値を取得した。申込者数は同ページに掲載が無いため null としている。過去年度の系列は未取得で、次回の更新時に追加する。31,046÷66,401=46.76%で、公表値46.8%と小数第1位まで一致することを検算済み。","unit_labels":{"applicants":"申込者数(未公表)","examinees":"受験者数","passers":"合格者数","pass_rate":"合格率(%)"},"public_note":"実施団体が公表している全国集計です。申込者数は公表されていないため掲載していません。"}}')
