-- 消防設備士 乙種第6類
INSERT INTO entities (type, slug, name, category, attributes, official_stats)
VALUES ('certification', 'shoubou-setsubi-otsu6', '消防設備士 乙種第6類', '技能・技術', '{"short_name":"消防設備士乙6","authority":{"name":"一般財団法人 消防試験研究センター","url":"https://www.shoubo-shiken.or.jp/"},"exam":{"eligibility":"乙種は受験資格の制限なし。公式サイトに「誰でも受験できます。」と明記されている(甲種は学歴・資格・実務経験のいずれかの要件が必要)。","fee_yen":4400,"format":"筆記試験と実技試験の両方がある。乙種第6類が扱うのは消火器で、乙種の免状でできるのは整備と点検まで(工事は甲種の免状が必要)。実技は「鑑別等」5問のみで、甲種に課される「製図」は乙種にはない。筆記は「消防関係法令」10問(共通6問・類別4問)、「基礎的知識(機械)」5問、「構造・機能・整備」15問(機械9問・規格6問)の計30問。","questions":35,"duration_minutes":105,"passing_criteria":"筆記は科目ごとの成績が40%以上で、かつ全体の成績が60%以上であること。実技は60%以上であること。筆記と実技の両方を満たす必要がある。","exemption":"既に持っている資格によって免除の範囲と試験時間が変わる。甲種第1類〜第4類または乙種第1類〜第4類・第7類の免状があると「消防関係法令(共通)」が免除され90分に、甲種第5類または乙種第5類だと共通と類別の両方が免除され75分になる。技術士(機械部門)などの場合は基礎的知識・構造機能整備・規格が免除され45分、資格が重なると最短35分になる。なお電気工事士・電気主任技術者の資格だけでは、乙種第6類の免除は受けられない(105分のまま)。","result_announcement":"受験者全員に、合否と正答率を記載した「試験結果通知書」が送付される。あわせて合格者の受験番号がホームページに掲示される。","source_urls":{"eligibility":"https://www.shoubo-shiken.or.jp/shoubou/annai/qualified.html","fee_yen":"https://www.shoubo-shiken.or.jp/shoubou/guide.html","format":"https://www.shoubo-shiken.or.jp/shoubou/annai/subject.html","questions":"https://www.shoubo-shiken.or.jp/shoubou/annai/subject.html","duration_minutes":"https://www.shoubo-shiken.or.jp/pdf_files/r0705_otu.pdf","passing_criteria":"https://www.shoubo-shiken.or.jp/shoubou/annai/way.html","exemption":"https://www.shoubo-shiken.or.jp/pdf_files/r0705_otu.pdf","result_announcement":"https://www.shoubo-shiken.or.jp/info/pass_s.html"},"subjects":["消防関係法令(共通) 6問","消防関係法令(類別) 4問","基礎的知識(機械) 5問","構造・機能・整備(機械) 9問","構造・機能・整備(規格) 6問","実技(鑑別等) 5問"],"questions_note":"筆記30問と実技5問の合計を questions としている。実技は記述式のため、筆記と同じ「問題数」で比べられる性質のものではない点に注意。","fee_note":"乙種の受験手数料(消費税非課税)。","retrieved_at":"2026-07-26"},"related":[{"slug":"kikenbutsu-otsu4","reason":"同じ消防試験研究センターが実施する試験。都道府県ごとに随時実施される点も共通"},{"slug":"kikenbutsu-otsu6","reason":"名前がよく似ているが別の試験。こちらは危険物取扱者の乙種第6類"}],"schedule_url":"https://shinsei.shoubo-shiken.or.jp/shoubou_ia/iajs9001.do?menjo_kbn=1","schedule_url_note":"このURLは試験日程の一覧表ではなく検索フォーム画面。都道府県を選んで日程を照会する形式である点に注意。","verification":{"collected_by":"researcher(一次ソースのみ)+ PM(Fable)","verified_by":"未実施","verified_at":null,"result":"🔴 独立検証が未実施。統計は5年度分を取得し、3通りの読み取り位置照合と合格者数÷受験者数の検算を全年度で通している。未検証の中心は科目免除の条件と、実技試験の内容の記述。"},"notes":"確認できなかった項目: (1) 実施頻度。公式サイトには「実施する試験の種類、日時は各支部へ問い合わせ」とあり、全国一律の回数の記載がない。(2) 電気工事士・電気主任技術者を持つ場合に他の類と併願したときの試験時間の一般式。公式PDFには乙種第4類・第7類の組合せ表しかなく、乙種第6類の個別記載がない。いずれも推測で埋めていない。","public_note":"この資格で扱えるのは消火器です。乙種の免状でできるのは整備と点検までで、工事には甲種の免状が必要です。名前がよく似た「危険物取扱者 乙種第6類」は別の試験です。"}', '{"official_stats":{"unit":"全国集計(乙種第6類, 消防試験研究センター発表)","series":[{"year":"令和7年度","applicants":42082,"examinees":32400,"passers":11541,"pass_rate":35.6,"source_url":"https://www.shoubo-shiken.or.jp/result/7/","retrieved_at":"2026-07-26"},{"year":"令和6年度","applicants":33393,"examinees":25835,"passers":9345,"pass_rate":36.2,"source_url":"https://www.shoubo-shiken.or.jp/result/6/","retrieved_at":"2026-07-26"},{"year":"令和5年度","applicants":32327,"examinees":25136,"passers":9567,"pass_rate":38.1,"source_url":"https://www.shoubo-shiken.or.jp/result/5/","retrieved_at":"2026-07-26"},{"year":"令和4年度","applicants":32151,"examinees":25023,"passers":9712,"pass_rate":38.8,"source_url":"https://www.shoubo-shiken.or.jp/result/r04/","retrieved_at":"2026-07-26"},{"year":"令和3年度","applicants":32888,"examinees":25634,"passers":10240,"pass_rate":39.9,"source_url":"https://www.shoubo-shiken.or.jp/result/r03/","retrieved_at":"2026-07-26"}],"source_url":"https://www.shoubo-shiken.or.jp/result/","retrieved_at":"2026-07-26","notes":"年度ページの消防設備士の集計表から乙種第6類の行を抽出した。この表は自動抽出で行がずれた実績があるため、(1)危険物取扱者 乙種第4類の既知値、(2)消防設備士の乙種第4類・第7類の値、(3)前年度ページに参考として載る当該年度の値、の3通りで読み取り位置を照合している。あわせて全年度で合格者数÷受験者数が公表合格率と小数第1位まで一致することを検算済み。令和7年度は申請者が前年度から約26%増えているが、実施団体はその理由を公表していない。","unit_labels":{"applicants":"申請者数(申込者数)","examinees":"受験者数(実際に受験した人数)","passers":"合格者数","pass_rate":"合格率(%)"},"public_note":"公式の集計表から乙種第6類の行を抜き出したものです。他の類や甲種は含みません。申請者数と受験者数の差(令和7年度は約9,700人)は、申し込んだものの当日受験しなかった人数にあたります。"}}')
